import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

// Dòng lệnh này tắt hoàn toàn bộ nhớ đệm (cache) cho API này
export const dynamic = 'force-dynamic';

export async function GET(request: Request) {
  try {
    const filePath = path.join(process.cwd(), 'src', 'app', 'api', 'data', 'tinh_tp.json');
    const fileContents = fs.readFileSync(filePath, 'utf8');
    const rawData = JSON.parse(fileContents);
    
    // Biến Object khổng lồ thành một Mảng (Array) chuẩn
    const cityArray = Array.isArray(rawData) ? rawData : Object.values(rawData);
    
    return NextResponse.json(cityArray);
    
  } catch (error) {
    console.error("Lỗi đọc file Tỉnh/Thành phố:", error);
    return NextResponse.json(
      { error: 'Không thể tải dữ liệu Tỉnh/Thành phố' }, 
      { status: 500 }
    );
  }
}